let queueFilters={};
const uniqueValues=(rows,key)=>[...new Set(rows.map(r=>r[key]))].sort();
function queueGroups(rows){
 if(!rows.length)return empty('No IPCRs awaiting your action','Only records at your review stage appear here. Try another period or clear the filters.');
 return uniqueValues(rows,'unit').map(unit=>{const college=rows.filter(r=>r.unit===unit);return `<details class="hierarchy college-group" ${queueFilters.unit||queueFilters.search?'open':''}><summary><span><strong>${esc(unit)}</strong><small>${uniqueValues(college,'department').length} departments · ${uniqueValues(college,'owner').length} employees</small></span><span class="tag green">${college.length} pending IPCRs</span></summary><div class="hierarchy-body">${uniqueValues(college,'department').map(department=>{const records=college.filter(r=>r.department===department).sort((a,b)=>a.name.localeCompare(b.name)||a.period.localeCompare(b.period));return `<details class="hierarchy department-group" ${queueFilters.department||queueFilters.search?'open':''}><summary><strong>${esc(department)}</strong><span>${uniqueValues(records,'owner').length} employees · ${records.length} IPCRs</span></summary>${recordTable(records,'queue')}</details>`;}).join('')}</div></details>`;}).join('');
}
function groupedQueue(){
 const title=['Vice President','President'].includes(user.role)?'Approval Queue':'Review Queue';
 const rows=queue(db,user).map(r=>{const owner=db.users.find(u=>u.id===r.owner);return {...r,unit:owner?.unit||r.unit,department:owner?.department||r.department,name:owner?.name||r.name,type:owner?.type||r.type};});
 const guidance=user.role==='HR Personnel'?'Final detailed review before forwarding to the Vice President.':user.role==='Vice President'?'Only IPCRs forwarded by HR for your approval.':user.role==='President'?'Only IPCRs forwarded by the Vice President for final approval.':'Only IPCRs assigned to your review stage and organizational scope.';
 shell(heading(title,guidance)+`<div class="notice">College / office → Department → Employee. Open a college, then a department to review its employees.</div><section class="panel panel-body no-print" style="margin:20px 0"><div class="report-filters">${field('Search employee or IPCR','queue-search',queueFilters.search||'')}${selectField('Evaluation period','queue-period',db.periods,queueFilters.period,'All periods')}${selectField('College / office','queue-unit',uniqueValues(rows,'unit'),queueFilters.unit,'All assigned units')}${selectField('Department','queue-department',uniqueValues(rows.filter(r=>!queueFilters.unit||r.unit===queueFilters.unit),'department'),queueFilters.department,'All departments')}${selectField('Employment type','queue-type',['Teaching','Non-Teaching'],queueFilters.type,'All types')}</div><button class="btn btn-link btn-sm" id="clear-queue">Clear filters</button></section><div id="queue-groups">${queueGroups(filterRecords(rows,queueFilters))}</div>`,title);
 $('#queue-search').oninput=e=>{queueFilters.search=e.target.value;$('#queue-groups').innerHTML=queueGroups(filterRecords(rows,queueFilters));};
 for(const key of ['period','unit','department','type'])$('#queue-'+key).onchange=e=>{queueFilters[key]=e.target.value;if(key==='unit')queueFilters.department='';groupedQueue();};
 $('#clear-queue').onclick=()=>{queueFilters={};groupedQueue();};
}
function countChart(label,items){const max=Math.max(1,...items.map(i=>i.value));return `<section class="panel chart-panel"><h2>${esc(label)}</h2><div class="accessible-chart" role="img" aria-label="${esc(label+': '+items.map(i=>i.name+' '+i.value).join(', '))}">${items.map(i=>`<div class="group-bar"><span>${esc(i.name)}</span><div class="progress-track"><span style="width:${i.value/max*100}%"></span></div><strong>${i.value}</strong></div>`).join('')}</div></section>`;}
function analyticsPage(){
 const dean=user.role==='Dean';if(!dean&&user.role!=='HR Personnel')return forbidden();
 reportFilters.period ||=activePeriod().id;
 if(dean)reportFilters.unit=user.unit;
 const units=db.units.filter(u=>!dean||u.name===user.unit);
 shell(heading(dean?'Dean Analytics':'Reports & analytics',dean?`${esc(user.unit)} · College progress and final performance results.`:'Institution-wide employee progress and final performance results.',`<div class="actions">${!dean?'<button id="export-csv" class="btn btn-light">Export progress CSV</button>':''}<button id="print-report" class="btn btn-primary">${icon('printer')} Print report</button></div>`)+`<section class="panel panel-body no-print" style="margin-bottom:24px"><div class="report-filters">${selectField('Evaluation period','report-period',db.periods,reportFilters.period)}${dean?`<div class="field"><label>Assigned college</label><strong>${esc(user.unit)}</strong></div>`:selectField('College / office','report-unit',units.map(u=>u.name),reportFilters.unit,'All units')}${selectField('Department','report-department',[...new Set(units.filter(u=>!reportFilters.unit||u.name===reportFilters.unit).flatMap(u=>u.departments))],reportFilters.department,'All departments')}${selectField('Employment type','report-type',['Teaching','Non-Teaching'],reportFilters.type,'All types')}${selectField('Progress / reviewer','report-status',[...PROGRESS_STATES,...STAGES.slice(0,5)],reportFilters.status,'All progress')}${selectField('Submission','report-submission',[{id:'yes',name:'Has submitted'},{id:'no',name:'Has not submitted'}],reportFilters.submission,'Everyone')}${field('Search employee or IPCR','report-search',reportFilters.search||'')}</div><button class="btn btn-link btn-sm" id="clear-reports">Clear filters</button></section><div id="report-results"></div>`,dean?'Dean Analytics':'Reports & Analytics');
 for(const key of ['period','unit','department','type','status','submission']){const el=$('#report-'+key);if(el)el.onchange=e=>{reportFilters[key]=e.target.value;if(key==='unit')reportFilters.department='';analyticsPage();};}
 $('#report-search').oninput=e=>{reportFilters.search=e.target.value;analyticsResults();};
 $('#clear-reports').onclick=()=>{reportFilters={period:activePeriod().id};analyticsPage();};
 $('#print-report').onclick=()=>window.print();
 if($('#export-csv'))$('#export-csv').onclick=()=>{const rows=employeeProgress(db,user,reportFilters);const url=URL.createObjectURL(new Blob([progressCsv(rows,db)],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='E-IPCR-employee-progress.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${rows.length} employee progress entries.`);};
 analyticsResults();
}
function progressTable(rows){return `<div class="table-wrap"><table class="records-table progress-table"><thead><tr><th>Employee / employment type</th><th>College / office · Department</th><th>Evaluation period</th><th>Current progress / reviewer</th><th>Submission</th><th>Final rating / IPCR</th></tr></thead><tbody>${rows.map(r=>`<tr data-employee="${esc(r.id)}"><td><strong>${esc(r.name)}</strong><small>${esc(r.type)}</small></td><td>${esc(r.unit)}<small>${esc(r.department)}</small></td><td>${esc(periodName(r.period))}</td><td>${badge(r.state)}<small>${r.reviewer?'With '+esc(r.reviewer):r.state==='Returned'?'Returned for correction':''}</small></td><td>${r.submitted?'Has submitted':'Has not submitted'}</td><td>${r.finalRating?`<strong>${fmt(r.finalRating.total)}</strong><small>${esc(r.finalRating.label)}</small>`:'—'}${r.record&&r.record.status!=='Draft'?link('View IPCR','detail/'+r.record.id,'btn btn-link btn-sm'):''}${r.record?.status==='Draft'?'<small>Private draft</small>':''}</td></tr>`).join('')||'<tr><td colspan="6">No eligible employees match these filters.</td></tr>'}</tbody></table></div>`;}
function scopeSummary(rows,label,unit,department=''){
 const t=progressTotals(rows);return `<tr><td><button class="btn btn-link btn-sm" data-drill-unit="${esc(unit)}" data-drill-department="${esc(department)}">${esc(label)}</button></td><td>${t.expected}</td>${PROGRESS_STATES.map(s=>`<td>${t.counts[s]}</td>`).join('')}<td>${t.submissionPercent}%<small>${t.submitted}/${t.expected}</small></td><td>${t.completionPercent}%<small>${t.completed}/${t.expected}</small></td></tr>`;
}
function analyticsResults(){
 const rows=employeeProgress(db,user,reportFilters),t=progressTotals(rows),dean=user.role==='Dean';
 // Progress and search narrow charts/list; denominators remain the eligible organizational roster.
 const roster=employeeProgress(db,user,{period:reportFilters.period,unit:reportFilters.unit,department:reportFilters.department,type:reportFilters.type});
 const denominator=progressTotals(roster);
 const finalRows=rows.filter(r=>r.finalRating);
 const scopeUnits=db.units.filter(u=>(!dean||u.name===user.unit)&&(!reportFilters.unit||u.name===reportFilters.unit));
 const headers=`<th>College / department</th><th>Eligible</th>${PROGRESS_STATES.map(s=>`<th>${esc(s)}</th>`).join('')}<th>Submitted %</th><th>Completed %</th>`;
 const summary=scopeUnits.map(unit=>{const people=roster.filter(r=>r.unit===unit.name);return `${!reportFilters.department?scopeSummary(people,unit.name,unit.name):''}${unit.departments.filter(d=>!reportFilters.department||d===reportFilters.department).map(d=>scopeSummary(people.filter(r=>r.department===d),'↳ '+d,unit.name,d)).join('')}`;}).join('');
 const leaders=scopeUnits.flatMap(unit=>unit.departments.filter(d=>!reportFilters.department||d===reportFilters.department).map(department=>{const winners=departmentLeaders(roster.filter(r=>r.unit===unit.name&&r.department===department),dean);return `<tr><td>${esc(unit.name)}<small>${esc(department)}</small></td><td>${winners.length?winners.map(w=>`<strong>${esc(w.name)}</strong> <span class="tag green">${fmt(w.finalRating.total)}</span>`).join('<br>'):'No final ratings yet.'}${winners.length>1?'<small>Tied highest final approved rating</small>':''}</td></tr>`;})).join('');
 $('#report-results').innerHTML=`<div class="print-heading"><h1>${dean?'Dean Analytics':'HR Reports & Analytics'}</h1><p>${esc(periodName(reportFilters.period))} · ${esc(reportFilters.unit||'All colleges / offices')} · ${esc(reportFilters.department||'All departments')}</p></div><div class="scope-trail"><strong>${esc(reportFilters.unit||'Institution-wide')}</strong><span> → ${esc(reportFilters.department||'All departments')} → Employees</span></div><div class="metrics">${metric('Eligible employees',denominator.expected,esc(periodName(reportFilters.period)),'people')}${metric('Submission progress',denominator.submissionPercent+'%',`${denominator.submitted} of ${denominator.expected} have submitted`,'send')}${metric('Completion',denominator.completionPercent+'%',`${denominator.completed} of ${denominator.expected} finally approved`,'patch-check')}${metric('Have not submitted',denominator.expected-denominator.submitted,'Includes employees with no IPCR','hourglass-split')}</div><p class="small muted">Percentages use all active employees explicitly assigned to this period in the selected college, department and employment type. Search, progress and submission filters narrow the charts and employee list below; they do not reduce this denominator.</p><div class="two-col">${countChart('Submission and completion · filtered employees',[{name:'Has submitted',value:t.submitted},{name:'Has not submitted',value:t.expected-t.submitted},{name:'Completed',value:t.completed}])}${countChart('Status distribution · filtered employees',PROGRESS_STATES.map(name=>({name,value:t.counts[name]})))}${countChart('Final rating distribution · completed IPCRs',db.settings.scale.map(s=>({name:s.label,value:finalRows.filter(r=>r.finalRating.label===s.label).length})))}</div><section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>College and department progress</h2><p class="small muted">Click a unit or department to drill down. Counts cover its eligible roster.</p></div></div><div class="table-wrap"><table class="records-table"><thead><tr>${headers}</tr></thead><tbody>${summary}</tbody></table></div></section><section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>Highest-performing ${dean?'faculty':'employees'} by department</h2><p class="small muted">Prototype results · computation and eligibility rules require MMSU confirmation. Only completed IPCRs with final approved ratings. Search and progress filters do not change department leaders.</p></div></div><div class="table-wrap"><table class="records-table"><thead><tr><th>College / office · Department</th><th>Employee(s) and final approved rating</th></tr></thead><tbody>${leaders}</tbody></table></div></section><section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>Employee progress</h2><p class="small muted">${rows.length} of ${denominator.expected} eligible employees match the filters. Submitted = with Department Head; under review = with Dean, HR, Vice President or President.</p></div><span class="tag">${rows.length} results</span></div>${progressTable(rows)}</section><p class="small muted">One entry per employee and period. A finally approved record takes precedence; otherwise the latest submitted record, then the latest draft. Rankings use the latest completed rated IPCR per employee. A draft or pending IPCR never replaces a final rating.</p>`;
 $$('[data-drill-unit]').forEach(button=>button.onclick=()=>{reportFilters.unit=button.dataset.drillUnit;reportFilters.department=button.dataset.drillDepartment;analyticsPage();});
}
